// Generic milestone advancer -- any workflow can POST {leadId, event} here
// instead of inventing its own stage/yardi_milestone write. Maps a domain
// event to the target {stage, yardi_milestone} using the SAME vocabulary as
// index.html's LEAD_STAGES / YARDI_MILESTONES_BY_STAGE, and only ever moves a
// lead FORWARD -- never overwrites a later stage/substage with an earlier
// one, so a delayed/duplicate/out-of-order call can't regress a lead that's
// already moved on. executed/dead are terminal for this path -- those only
// change by a human editing the lead by hand in the app.
// (2026-08-25, built per Justin's ask after workflow 33 was found sending
// qualifying emails without ever advancing the lead's milestone.)

const STAGE_RANK = { lead: 0, tour: 1, proposal: 2, negotiation: 3, executed: 4, dead: 99 };

// Only the events actually wired to a caller so far (workflow 33, event
// "qualifying_email_sent"). Add an entry here -- and wire an HTTP node in the
// relevant workflow -- for each new milestone another workflow should set;
// the mapping lives in exactly one place instead of every workflow
// reinventing its own milestone string.
const EVENT_MAP = {
  qualifying_email_sent:    { stage: 'lead',        yardi_milestone: 'Lead Contacted (Sales)' },
  lead_followup_sent:       { stage: 'lead',         yardi_milestone: 'Lead Follow Up' },
  tour_scheduled:           { stage: 'tour',         yardi_milestone: 'Tour Scheduled (Sales)' },
  credit_app_sent:          { stage: 'tour',         yardi_milestone: 'Credit App Sent to Lead' },
  credit_app_submitted:     { stage: 'tour',         yardi_milestone: 'Credit App Submitted (Sales)' },
  proposal_submitted:       { stage: 'proposal',     yardi_milestone: 'Proposal Submitted (Sales)' },
  signed_proposal_uploaded: { stage: 'negotiation',  yardi_milestone: 'Signed Proposal Uploaded (Sales)' },
};

// Only orders substages WITHIN the 'lead' stage. Waitlist (Sales) / Cold Lead
// (Sales) are side-branches, not "further along" -- deliberately left out so
// they get the same never-overwrite protection as any unrecognized milestone.
const LEAD_SUBSTAGE_RANK = { 'Lead Assigned': 0, 'Lead Contacted (Sales)': 1, 'Lead Follow Up': 2 };

function fsVal(field) {
  if (!field) return null;
  if (field.stringValue  !== undefined) return field.stringValue;
  if (field.integerValue !== undefined) return Number(field.integerValue);
  if (field.doubleValue  !== undefined) return field.doubleValue;
  if (field.booleanValue !== undefined) return field.booleanValue;
  if (field.nullValue    !== undefined) return null;
  if (field.mapValue) { const out = {}; for (const [k, v] of Object.entries(field.mapValue.fields || {})) out[k] = fsVal(v); return out; }
  if (field.arrayValue) return (field.arrayValue.values || []).map(fsVal);
  return null;
}

const req = $('Advance milestone webhook').item.json.body || {};
const { leadId, event } = req;
if (!leadId) throw new Error('Missing body.leadId');
if (!event)  throw new Error('Missing body.event');

const target = EVENT_MAP[event];
if (!target) {
  return [{ json: { shouldWrite: false, leadId, event, reason: `Unknown event "${event}". Known events: ${Object.keys(EVENT_MAP).join(', ')}` } }];
}

const getResp = $('Get current lead').item.json || {};
// A 404 (bad leadId) comes back from continueOnFail as an error-shaped item,
// not a Firestore document -- getResp.fields will be undefined either way,
// so an unknown lead just falls through to the "treat as brand new" default.
const current = { stage: 'lead', yardi_milestone: '' };
if (getResp.fields) {
  const f = getResp.fields;
  if (f.stage) current.stage = fsVal(f.stage) || 'lead';
  if (f.yardi_milestone) current.yardi_milestone = fsVal(f.yardi_milestone) || '';
}

const curRank = STAGE_RANK[current.stage] ?? 0;
const targetRank = STAGE_RANK[target.stage] ?? 0;

let shouldWrite = false;
if (targetRank > curRank) {
  shouldWrite = true; // moving to a stage entirely further along
} else if (targetRank === curRank && target.stage === 'lead') {
  // Same stage -- only the 'lead' stage has more than one wired event so
  // far, so only it needs substage ordering. Add per-stage substage ranks
  // here if tour/proposal/negotiation ever get a second wired event each.
  const curSub = LEAD_SUBSTAGE_RANK[current.yardi_milestone] ?? -1; // unrecognized (incl. Waitlist/Cold) = protected
  const targetSub = LEAD_SUBSTAGE_RANK[target.yardi_milestone] ?? -1;
  shouldWrite = curSub >= 0 && targetSub > curSub;
} // targetRank < curRank, or same-stage-non-lead -> never (would regress)

if (!shouldWrite) {
  return [{ json: { shouldWrite: false, leadId, event, currentStage: current.stage, currentMilestone: current.yardi_milestone, reason: 'Lead is already at or past this milestone -- not overwriting.' } }];
}

const now = new Date().toISOString();
const patchFields = { stage: target.stage, yardi_milestone: target.yardi_milestone, updatedAt: now };
function toFs(v) { return { stringValue: String(v) }; }
const patchBody = { fields: Object.fromEntries(Object.entries(patchFields).map(([k, v]) => [k, toFs(v)])) };

return [{ json: {
  shouldWrite: true, leadId, event,
  fromStage: current.stage, fromMilestone: current.yardi_milestone,
  toStage: target.stage, toMilestone: target.yardi_milestone,
  patchBody, updateMask: Object.keys(patchFields).join('&updateMask.fieldPaths=')
} }];
